import sys, numpy as np, time, itertools
sys.path.insert(0,'/workspace/submission')
from te.algorithms.formulations.path_based.distributed.worker import solve_worker_proposal, WorkerProblem, tol

def verify(cap, dem, slots, mode, rho, bias, owned, prop):
    """Independent certificate check straight from the protocol text."""
    errs=[]
    live=cap>0
    E=len(cap)
    avail={k:[ (slots[k][t] is not None and all(live[e] for e in slots[k][t])) for t in range(len(slots[k]))] for k in owned}
    x={}
    for i,k in enumerate(owned):
        for t,v in enumerate(prop['flow'][i]):
            x[(k,t)]=v
    # L
    L=np.zeros(E)
    for (k,t),v in x.items():
        if slots[k][t] is not None:
            for e in slots[k][t]: L[e]+=v
    for e in range(E):
        if not live[e] and L[e]!=0: errs.append(f'load nonzero on withdrawn {e}')
        if abs(L[e]-prop['edge_load'][e])>tol(L[e],prop['edge_load'][e]): errs.append(f'load mismatch {e}')
    R=sum(x.values())
    f=0.5*sum(v*v for v in x.values())+0.5*rho*sum(((L[e]/cap[e]-bias[e])**2 for e in range(E) if live[e]))-(R if mode=='admit' else 0)
    G={}
    for i,k in enumerate(owned):
        if dem[k]<=0: continue
        for t in range(len(slots[k])):
            if not avail[k][t]: continue
            G[(k,t)]=x[(k,t)]+rho*sum(((L[e]/cap[e]-bias[e])/cap[e] for e in slots[k][t]))-(1 if mode=='admit' else 0)
    lam={k:prop['potential'][i] for i,k in enumerate(owned)}
    for i,k in enumerate(owned):
        if dem[k]==0 and lam[k]!=0: errs.append('zero demand potential nonzero')
        if mode=='admit' and lam[k]<0: errs.append('negative admit potential')
        for t in range(len(slots[k])):
            if dem[k]<=0 or not avail[k][t]:
                if x[(k,t)]!=0: errs.append('nonzero on unavailable/zero demand')
            else:
                if G[(k,t)]+lam[k] < -tol(G[(k,t)]+lam[k],0): errs.append(f'G+lam viol {k} {t} {G[(k,t)]+lam[k]}')
        if mode=='route':
            s=sum(x[(k,t)] for t in range(len(slots[k])))
            if abs(s-dem[k])>tol(s,dem[k]): errs.append(f'route sum {k} {s} vs {dem[k]}')
        else:
            s=sum(x[(k,t)] for t in range(len(slots[k])))
            if s-dem[k]>tol(s,dem[k]): errs.append(f'admit sum {k}')
    D=f-sum(x[k]*g for k,g in G.items())-sum(dem[k]*lam[k] for k in owned)
    if abs(f-D)>tol(f,D): errs.append(f'gap {abs(f-D)} tol {tol(f,D)} f={f}')
    return errs

rng=np.random.default_rng(7)
def make_case(seed, maxk=6):
    r=np.random.default_rng(seed)
    K=int(r.integers(1,maxk+1)); E=int(r.integers(1,12))
    cap=r.integers(0,4,size=E).astype(float)
    slots=[]; dem=[]
    for k in range(K):
        npth=int(r.integers(1,4))
        ps=[]
        for t in range(npth):
            L=int(r.integers(1,min(4,E)+1))
            ps.append(tuple(int(e) for e in r.integers(0,E,size=L)))
        if r.random()<0.2: ps=list(ps)+[None]
        slots.append(ps); dem.append(float(r.integers(0,5)))
    return cap,np.array(dem),slots

t0=time.time(); bad=0; n=0
for seed in range(300):
    cap,dem,slots=make_case(seed)
    E=len(cap)
    owned=list(range(len(slots)))
    bias=rng.normal(size=E)*0.5* (cap>0)
    rho=float(rng.integers(1,9))
    for mode in ('route','admit'):
        prop=solve_worker_proposal(owned,cap,dem,slots,mode,rho,bias,E)
        n+=1
        if prop['status']=='infeasible':
            exp=sorted(k for k in owned if dem[k]>0 and not any(slots[k][t] is not None and all(cap[e]>0 for e in slots[k][t]) for t in range(len(slots[k]))))
            if mode=='route' and prop['unroutable']!=exp: print('INFEAS MISMATCH',prop['unroutable'],exp); bad+=1
            continue
        errs=verify(cap,dem,slots,mode,rho,bias,owned,prop)
        if errs:
            bad+=1
            if bad<6: print('seed',seed,mode,'rho',rho,'errs',errs[:3])
print('bad',bad,'of',n,'time',time.time()-t0)
